  public function executeDevolverTodos()
  {
  	/*******************************Cambiar Estado Del Prestamo****************************************************/
  	$prestamo = PrestamoPeer::retrieveByPK($this->getRequestParameter('prestamo_id'));
  	$prestamo->setEstadoprestamoId(2);
  	$prestamo->setFechaDevolucion(date("Y-m-d G:i:s"));
  	$prestamo->save();
	/**************************************************************************************************************/  	
  	
  	/***********************Cambiar Estado De Los Detalles del Prestamo********************************************/
  	$c = new Criteria();
  	$c->add(DetallePrestamoPeer::PRESTAMO_ID,$this->getRequestParameter('prestamo_id'));
  	$c->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,1);
  	$prestados =  DetallePrestamoPeer::doSelect($c);
	foreach($prestados as $result){
		$result->setEstadoprestamoId(2);		
		$result->save();
	}    
	/**************************************************************************************************************/
	//$this->redirect('prestamo/show?prestamo_id='.$prestamo->getPrestamoId());
	$this->redirect('prestamo/show?prestamo_id='.$this->getRequestParameter('prestamo_id'));	
  }
  
  public function executeUpdateDevolver()
  {   	 	
  	/************************Cambio Estado de la solicitud en la tabla DetallePrestamo*****************************/
  	$paginaActual=$this->getRequestParameter('page');
  	/***********************************************************************************************************/
  	echo $this->getRequestParameter('solicitudprestamo_id');
  	$c =  new Criteria();
  	$c->add(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,$this->getRequestParameter('solicitudprestamo_id'));
  	$resp  = DetallePrestamoPeer::doSelectOne($c);  	  	
	$resp->setEstadoprestamoId(2);
	$resp->save();
	/**************************************************************************************************************/
	
	/*************************Cambio Estado de la solicitud en la tabla SolicitudPrestamo***************************
	$solicitud_prestamo = SolicitudPrestamoPeer::retrieveByPK($this->getRequestParameter('solicitudprestamo_id'));
	$solicitud_prestamo->setSolicitudprestamoestadoId(1);
	$solicitud_prestamo->save();
	/**************************************************************************************************************/
	
	/***********************Verifica Estado de la solicitud Para asi Cambiar estado del Prestamo*******************/
	$a = new Criteria();
	$a->add(DetallePrestamoPeer::PRESTAMO_ID,$this->getRequestParameter('prestamo_id'));
	$a->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,1);
	$temp = DetallePrestamoPeer::doCount($a);
