  public function executeUpdateRestaurarPrestamo()
  {   	 	
  	/************************Cambio Estado de la solicitud en la tabla DetallePrestamo**********************************************/
    $usuariologueado  = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $usuario = UsuarioPeer::retrieveByPK($usuariologueado);
  	$paginaActual=$this->getRequestParameter('page');
    $observaciones_prestamo = "Prestamo Restaurado Por: ".$usuario->getNombre()." ".$usuario->getApellido."=>El ".date("Y-m-d G:i:s");    
  	/********************************************************************************************************************************/  	
  	$c =  new Criteria();
  	$c->add(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,$this->getRequestParameter('solicitudprestamo_id'));
  	$resp  = DetallePrestamoPeer::doSelectOne($c);  	  	
	$resp->setEstadoprestamoId(1);
	$resp->save();
	/**************************************************************************************************************/		
	
	/***********************Verifica Estado de la solicitud Para asi Cambiar estado del Prestamo*******************/
	$a = new Criteria();
	$a->add(DetallePrestamoPeer::PRESTAMO_ID,$this->getRequestParameter('prestamo_id'));
	$a->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,2);
	$temp = DetallePrestamoPeer::doCount($a);
	if($temp == 0){
		$prestamo = PrestamoPeer::retrieveByPK($this->getRequestParameter('prestamo_id'));
		$prestamo->setEstadoprestamoId(1);
		$prestamo->setFechaDevolucion(null);
        if(trim($prestamo->getObservaciones()) != ""){
           $observaciones_prestamo = $prestamo->getObservaciones()."=>".$observaciones_prestamo;
        }
        $prestamo->setObservaciones($observaciones_prestamo);
		$prestamo->save();
	}	
	/**************************************************************************************************************/
	$this->redirect('prestamo/show?page='.$paginaActual.'&prestamo_id='.$this->getRequestParameter('prestamo_id'));		
  }
  	
  public function executeUpdate()
  {
    if (!$this->getRequestParameter('prestamo_id'))
    {
      $prestamo = new Prestamo();
    }
    else
    {
      $prestamo = PrestamoPeer::retrieveByPk($this->getRequestParameter('prestamo_id'));
      $this->forward404Unless($prestamo);
    }

    //$prestamo->setPrestamoId($this->getRequestParameter('prestamo_id'));
    $prestamo->setUsuarioId($this->getRequestParameter('usuario_id') ? $this->getRequestParameter('usuario_id') : null);
    $prestamo->setPeriodoId($this->getRequestParameter('periodo_id') ? $this->getRequestParameter('periodo_id') : null);
    if ($this->getRequestParameter('fecha_prestamo'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_prestamo'), $this->getUser()->getCulture());
      $prestamo->setFechaPrestamo("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_vencimiento'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_vencimiento'), $this->getUser()->getCulture());
      $prestamo->setFechaVencimiento("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_devolucion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_devolucion'), $this->getUser()->getCulture());
      $prestamo->setFechaDevolucion("$y-$m-$d");
    }
    $prestamo->setObservaciones($this->getRequestParameter('observaciones'));
    $prestamo->setConsecutivoRegional($this->getRequestParameter('consecutivo_regional'));

    $prestamo->save();

    return $this->redirect($this->getRequest()->getScriptName().'/prestamo/show?prestamo_id='.$prestamo->getPrestamoId());
  }
  
