		$c->addJoin(PrestamoPeer::PRESTAMO_ID, DetallePrestamoPeer::PRESTAMO_ID);
	    $c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID, SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
	    $c->addJoin(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);	    
	    $c->add(UnidadDocumentalPeer::CODIGO_BARRAS,$this->getRequestParameter('CodBarras').'%',Criteria::LIKE);
		$parametros .= "&CodBarras=".$this->getRequestParameter('CodBarras');			
	}
	//***********************************************************************************************
	if($this->getRequestParameter('usuario_id')){		
		$c->addJoin(PrestamoPeer::PRESTAMO_ID, DetallePrestamoPeer::PRESTAMO_ID);
	    $c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID, SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
	    $c->add(SolicitudPrestamoPeer::USUARIO_ID,$this->getRequestParameter('usuario_id'));
		$parametros .= "&usuario_id=".$this->getRequestParameter('usuario_id');		
	}
	//***********************************************************************************************
	if($this->getRequestParameter('regional_id')){
		$c->add(PrestamoPeer::REGIONAL_ID, $this->getRequestParameter('regional_id'));
		$parametros .= "&regional_id=".$this->getRequestParameter('regional_id');		
	}
	//***********************************************************************************************
	if($this->getRequestParameter('dependencia_id')){			
		$c->addJoin(PrestamoPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID);
	    $c->addJoin(UsuarioPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID);
	    $c->add(DependenciaPeer::DEPENDENCIA_ID,$this->getRequestParameter('dependencia_id'));
		$parametros .= "&dependencia_id=".$this->getRequestParameter('dependencia_id');			
	}
	//***********************************************************************************************
	if($this->getRequestParameter('estado_prestamo_id')){
		$c->addJoin(DetallePrestamoPeer::PRESTAMO_ID,PrestamoPeer::PRESTAMO_ID);		
		$c->add(PrestamoPeer::ESTADOPRESTAMO_ID, $this->getRequestParameter('estado_prestamo_id'));
		$parametros .= "&estado_prestamo_id=".$this->getRequestParameter('estado_prestamo_id');		
	}
	//***********************************************************************************************
	if ($this->getRequestParameter('fechaInicial')) {
			if ($this->getRequestParameter('fechaFinal')) {
	            $c->add(PrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaInicial').' 00:00:00',Criteria::GREATER_THAN);
	            $c->addAnd(PrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaFinal').' 23:59:59',Criteria::LESS_THAN);
	            $parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial').' 00:00:00'."&fechaFinal=".$this->getRequestParameter('fechaFinal').' 23:59:59';
	        }else{
			    $c->add(PrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaInicial'),Criteria::GREATER_THAN);
			    $parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial').' 00:00:00';
		    }
	    }	    	    
	//***********************************************************************************************
	if($this->getRequestParameter('titulo')){			
		$c->addJoin(PrestamoPeer::PRESTAMO_ID, DetallePrestamoPeer::PRESTAMO_ID);
	    $c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID, SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
	    $c->addJoin(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);	    
	    $c->add(UnidadDocumentalPeer::TITULO,$this->getRequestParameter('titulo').'%',Criteria::LIKE);
		$parametros .= "&titulo=".$this->getRequestParameter('titulo');			
	}
	//***********************************************************************************************
	if($this->getRequestParameter('subserie_id')){			
		$c->addJoin(PrestamoPeer::PRESTAMO_ID, DetallePrestamoPeer::PRESTAMO_ID);
	    $c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID, SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
	    $c->addJoin(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
		$c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID, SubseriePeer::SUBSERIE_ID);	    
	    $c->add(SubseriePeer::SUBSERIE_ID,$this->getRequestParameter('subserie_id'));
		$parametros .= "&subserie_id=".$this->getRequestParameter('subserie_id');			
	}
	//***********************************************************************************************
	if($this->getRequestParameter('responsable')){			
		$c->addJoin(PrestamoPeer::PRESTAMO_ID, DetallePrestamoPeer::PRESTAMO_ID);
	    $c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID, SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
	    $c->addJoin(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);	    
	    $c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID,$this->getRequestParameter('responsable'));
	    $c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID,1);
		$parametros .= "&responsable=".$this->getRequestParameter('responsable');			
	}
	//***********************************************************************************************
	if($this->getRequestParameter('prestadoPor')){
		$c->add(PrestamoPeer::USUARIO_ID, $this->getRequestParameter('prestadoPor'));
		$parametros .= "&prestadoPor=".$this->getRequestParameter('prestadoPor');		
	}
	//***********************************************************************************************
	if($this->getRequestParameter('vencidos')?true:false){
		$c->addJoin(PrestamoPeer::PRESTAMO_ID,DetallePrestamoPeer::PRESTAMO_ID);						
		$c->add(PrestamoPeer::FECHA_VENCIMIENTO, $this->getRequestParameter('vencidos'),Criteria::LESS_THAN);
		//$c->add(PrestamoPeer::FECHA_DEVOLUCION,$this->getRequestParameter('vencidos') ,Criteria::LESS_THAN);
		$parametros .= "&vencidos=".$this->getRequestParameter('vencidos');				
	}    
	//***********************************************************************************************
	 $criteria = clone $c;  // Clonamos el objeto para evitar modificar el original  
     $c->clearSelectColumns(); // Eliminamos la columnas de seleccion en caso de que esten definidas  
     //***********************************************************************************************
     $c->addSelectColumn(PrestamoPeer::CONSECUTIVO_REGIONAL);//0
     $c->addSelectColumn(UnidadDocumentalPeer::TITULO);//1
     $c->addSelectColumn(UnidadDocumentalPeer::CODIGO_BARRAS);//2
     $c->addSelectColumn(SeriePeer::DESCRIPCION);//3
     $c->addSelectColumn(SubseriePeer::DESCRIPCION);//4
     //$c->addSelectColumn(UsuarioPeer::USER_NAME);  
     $c->addSelectColumn(SolicitudPrestamoPeer::USUARIO_ID);//5
     $c->addSelectColumn(PrestamoPeer::FECHA_PRESTAMO);//6
     $c->addSelectColumn(PrestamoPeer::FECHA_DEVOLUCION);//7  
     $c->addSelectColumn(PrestamoPeer::FECHA_VENCIMIENTO);//8
     $c->addSelectColumn(UsuarioPeer::NOMBRE);//9
     $c->addSelectColumn(UsuarioPeer::APELLIDO);//10
     $c->addSelectColumn(EstadoPrestamoPeer::DESCRIPCION);//11
     //$c->addAsColumn('nombre',UsuarioPeer::USER_NAME);
     /*$c->addAsColumn('nombre','SELECT USER_NAME FROM '.UsuarioPeer::TABLE_NAME.','.SolicitudPrestamoPeer::TABLE_NAME.'
     WHERE '.SolicitudPrestamoPeer::USUARIO_ID.'='.UsuarioPeer::USUARIO_ID);*/
     //***********************************************************************************************
     // Hacemos joins  
     $c->addJoin(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID,UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
	 $c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID,SubseriePeer::SUBSERIE_ID);  
     $c->addJoin(SubseriePeer::SERIE_ID,SeriePeer::SERIE_ID);
	 $c->addJoin(PrestamoPeer::PRESTAMO_ID,DetallePrestamoPeer::PRESTAMO_ID);
     $c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
     $c->addJoin(PrestamoPeer::USUARIO_ID,UsuarioPeer::USUARIO_ID);
     $c->addJoin(PrestamoPeer::ESTADOPRESTAMO_ID,EstadoPrestamoPeer::ESTADOPRESTAMO_ID);
     //$c->addDescendingOrderByColumn(DetallePrestamoPeer::PRESTAMO_ID);
     //***********************************************************************************************
	 $arrOrigen = array();	
	 $prestamo = PrestamoPeer::doSelectStmt($c);
	 $this->prestamo = $prestamo;
	 //***********************************************************************************************	
	 $nombSol = array();				 
	 //***********************************************************************************************
  }
  
  public function executeDelete()
  {
    $prestamo = PrestamoPeer::retrieveByPk($this->getRequestParameter('prestamo_id'));

    $this->forward404Unless($prestamo);

    $prestamo->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/prestamo/list');
  }
  
  public function executeConsulta()
  {
  	$this->verificaPrilegio("prestamo/consulta");
  	$this->usuarios    = new Usuario();
  	$this->regional    = new Regional();
  	$this->dependencia = new Dependencia();
  	$this->estado 	   = new EstadoPrestamo();
  	$this->subserie    = new Subserie();
  	
	$this->mostrarUsuario=0;
    if($this->getRequestParameter('mostrarUsuario')==1){
        $c = new Criteria();
	    $c->addAscendingOrderByColumn(UsuarioPeer::NOMBRE);
	    $this->usuarios = UsuarioPeer::doSelect($c);
        //*****************************************************************************
        $s = new Criteria();        
        //*****************************************************************************
        $s->addJoin(SeriePeer::SERIE_ID,SubseriePeer::SERIE_ID);
        $s->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
        $s->addJoin(DependenciaPeer::ENTIDAD_ID,EntidadPeer::ENTIDAD_ID);
        //*****************************************************************************
		$s->addAscendingOrderByColumn(SubseriePeer::DESCRIPCION);
        $s->clearSelectColumns();
        //*****************************************************************************
        $s->addSelectColumn(SubseriePeer::SUBSERIE_ID);//0
	    $s->addSelectColumn(SubseriePeer::DESCRIPCION);//1
        $s->addSelectColumn(DependenciaPeer::NOMBRE);//2
        $s->addSelectColumn(DependenciaPeer::CODIGO);//3
        $s->addSelectColumn(EntidadPeer::DESCRIPCION);//4
		$this->subseries = SubseriePeer::doSelectStmt($s);
        $this->mostrarUsuario=1;
        //*****************************************************************************
    }  
  }
  
  public function getRegionalUser($idUser){
	$user  = UsuarioPeer::retrieveByPK($idUser);
	return $user->getRegionalId();
  }	
}
